const text = ($input.first().json.body?.msg || '').toLowerCase();
let reply = 'I can help with pricing, booking, voice agents, and recruitment automation.';
let scoreInc = 10;

if (/price|cost|₦|fee|rate/.test(text)) {
  reply = 'Retainers start at ₦150k/month. Would you like a tailored quote?';
  scoreInc = 35;
} else if (/book|call|demo|schedule|interview/.test(text)) {
  reply = 'Happy to book you in! Please choose a convenient slot on our booking calendar.';
  scoreInc = 40;
} else if (/voice|vapi|phone|agent/.test(text)) {
  reply = 'Our AI voice agents handle 24/7 candidate screening and customer intake seamlessly.';
  scoreInc = 25;
}

return [{ json: { text, reply, scoreInc } }];

const item = $input.first().json;
const newScore = Math.min(100, (item.scoreInc || 10) + 40);
const status = newScore >= 70 ? 'Qualified' : (newScore >= 35 ? 'Interested' : 'New');
return [{ json: { ...item, score: newScore, status } }];
